def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive_opps = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opps.append(opp)

    if not alive_opps:
        return float(min(budget, 20.0))

    units = int(supply // WATER_REQ)
    total_alive = 1 + len(alive_opps)
    tight = units < total_alive
    very_tight = units <= 1

    threat_bid = 0.0
    cindy_bid = 0.0
    eric_bid = 0.0
    cindy_budget = None
    eric_budget = None

    for opp in alive_opps:
        prev = opp.get('previous_trace', {})
        pbid = 0.0
        if prev and prev.get('bid') is not None:
            pbid = float(prev.get('bid', 0.0))
        if pbid > threat_bid:
            threat_bid = pbid
        req = opp.get('water_requirement', WATER_REQ)
        sal = opp.get('daily_salary', DAILY_SALARY)
        if req == 13 and sal == 70:
            if pbid > 300:
                cindy_bid = pbid
                cindy_budget = opp.get('budget', 0.0)
            elif pbid >= 100:
                eric_bid = pbid
                eric_budget = opp.get('budget', 0.0)

    if hp <= 2 or no_water_days >= 2:
        emergency = max(135.0, eric_bid + 3.0, threat_bid + 2.0)
        return float(min(budget, emergency))

    if very_tight:
        if eric_bid > 0:
            target = eric_bid + 2.0
        else:
            target = max(110.0, threat_bid + 2.0)
        if cindy_budget is not None and cindy_budget < 80:
            target = max(110.0, eric_bid + 2.0)
        return float(min(budget, target))

    if tight:
        if hp >= 7 and no_water_days == 0:
            conserve = 18.0
            if cindy_bid > 250 and cindy_budget is not None and cindy_budget < 100:
                conserve = 12.0
            return float(min(budget, conserve))
        target = max(95.0, eric_bid + 1.5)
        return float(min(budget, target))

    if hp <= 4 or no_water_days == 1:
        safe_bid = max(72.0, min(95.0, threat_bid * 0.7 if threat_bid > 0 else 72.0))
        return float(min(budget, safe_bid))

    low = 8.0
    if day >= 8:
        low = 20.0
    if cindy_bid > 250 and cindy_budget is not None and cindy_budget < 50:
        low = 5.0
    return float(min(budget, low))

def get_bid(day_context, my_status, opponents_status):
    DAILY_SALARY = 80
    WATER_REQ = 7
    supply = day_context['supply']
    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    if not yesterday_bids:
        return min(my_status['budget'], DAILY_SALARY * 0.6)

    max_prev = max(yesterday_bids)

    if my_status['hp'] <= 3:
        return min(my_status['budget'], DAILY_SALARY * 1.2)

    if supply < WATER_REQ * len(alive_opponents):
        return min(my_status['budget'], max_prev * 1.05 + 2)

    return min(my_status['budget'], max(DAILY_SALARY * 0.4, max_prev * 0.9))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 8
    DAILY_SALARY = 140
    supply = int(day_context['supply'])
    day = int(day_context['day'])
    hp = int(my_status['hp'])
    budget = float(my_status['budget'])
    no_water_days = int(my_status['no_water_days'])

    alive_opponents = {oid: o for oid, o in opponents_status.items() if o['alive']}
    if not alive_opponents:
        return min(budget, DAILY_SALARY * 0.4)

    # Gather yesterday's bids from alive opponents
    yesterday_bids = []
    for oid, opp in alive_opponents.items():
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(float(prev['bid']))

    # Determine base bid based on desperation
    if hp <= 0 or no_water_days > 1:
        base_bid = DAILY_SALARY * 0.9
    elif hp <= 2:
        base_bid = DAILY_SALARY * 0.7
    else:
        base_bid = DAILY_SALARY * 0.5

    # Adjust based on yesterday's highest bid
    if yesterday_bids:
        highest_prev = max(yesterday_bids)
        if highest_prev >= DAILY_SALARY * 0.85:
            # Opponents were aggressive yesterday; maybe they will be again
            # But we can try to save if we are not desperate
            if hp > 3 and no_water_days == 0:
                base_bid = max(base_bid, DAILY_SALARY * 0.3)
            else:
                base_bid = max(base_bid, DAILY_SALARY * 0.85)
        else:
            # Opponents were moderate; we can try to outbid by a small margin
            base_bid = max(base_bid, highest_prev + 1.5)

    # Ensure bid does not exceed budget and is at least a small amount
    bid = min(budget, base_bid)
    bid = max(bid, 1.0)
    return bid
